+fn setter_body(prop: &Property) -> TokenStream {
+    let name = &prop.name;
+    let modification = match (&prop.rust_type, prop.is_ref, prop.is_collection) {
+        (RustType::Custom(_), true, false) => quote!(append(val.properties.0.to_mut())),
